/// Returns the index of a minimum element in the suffix a[i..].
/// Precondition: i < a.len()
pub fn look_for_min(a: &[i32], i: usize) -> usize {
    debug_assert!(i < a.len(), "start index must be within the slice");

    let mut min_idx = i;
    for j in (i + 1)..a.len() {
        if a[j] < a[min_idx] {
            min_idx = j;
        }
    }
    min_idx
}

